SELECT no_plan();
CREATE TEMP TABLE cof_fixture(token text,attempt jsonb,authorization_id uuid,submission uuid,renewal_snapshot jsonb);
GRANT ALL ON cof_fixture TO service_role,authenticated;
INSERT INTO public.square_live_test_checkouts(amount_cents) VALUES(5);
INSERT INTO cof_fixture(token,submission,renewal_snapshot) SELECT token,gen_random_uuid(),(SELECT jsonb_agg(to_jsonb(p)) FROM public.rental_extension_periods p) FROM public.square_live_test_checkouts LIMIT 1;
SET LOCAL ROLE service_role;
SELECT is((SELECT get_square_live_test_details(token)->>'amount_cents' FROM cof_fixture),'5','Independent checkout is exactly five LIVE cents');
SELECT is((SELECT get_square_live_test_details(token)->>'can_pay' FROM cof_fixture),'true','Independent test is payable without a guest account');
SELECT throws_like($q$SELECT prepare_square_cof_checkout('live_test',token,submission,'{"givenName":"Test","familyName":"Payer","email":"payer@example.invalid","postalCode":"10003","country":"US"}','zonyx-square-cof-v1',repeat('terms ',30),'{}',false,true,'location') FROM cof_fixture$q$,'%Explicit card storage%','Unchecked storage consent cannot create an attempt');
UPDATE cof_fixture SET attempt=prepare_square_cof_checkout('live_test',token,submission,'{"givenName":"Test","familyName":"Payer","email":"payer@example.invalid","postalCode":"10003","country":"US"}','zonyx-square-cof-v1',repeat('terms ',30),'{}',true,true,'location');
UPDATE cof_fixture SET authorization_id=(attempt->>'authorization_id')::uuid;
SELECT ok((SELECT period_id IS NULL AND booking_id IS NULL AND test_id IS NOT NULL FROM square_renewal_payment_attempts WHERE id=(SELECT (attempt->>'id')::uuid FROM cof_fixture)),'Test has no booking or renewal association');
SELECT is((SELECT state FROM square_checkout_authorizations WHERE id=(SELECT authorization_id FROM cof_fixture)),'pending','Consent alone never claims card saved');
SELECT ok((SELECT accepted_at IS NOT NULL AND length(terms_sha256)=64 AND terms_version='zonyx-square-cof-v1' FROM square_checkout_authorizations WHERE id=(SELECT authorization_id FROM cof_fixture)),'Immutable terms version, hash, payer and server acceptance time recorded');
SELECT throws_like('SELECT claim_square_cof_dispatch(authorization_id,submission) FROM cof_fixture','%Square customer required%','Payment cannot dispatch before verified customer association');
UPDATE square_checkout_authorizations SET square_customer_id='square-customer' WHERE id=(SELECT authorization_id FROM cof_fixture);
SELECT is((SELECT claim_square_cof_dispatch(authorization_id,submission) FROM cof_fixture),true,'First consent-bound dispatch succeeds');
SELECT is((SELECT claim_square_cof_dispatch(authorization_id,submission) FROM cof_fixture),false,'Repeated dispatch cannot charge twice');
SELECT throws_like('SELECT confirm_square_checkout_card(authorization_id,''square-customer'',''ccof:fixture'',''1111'',''VISA'') FROM cof_fixture','%completed payment required%','Cannot mark card ready before completed payment');
SELECT record_square_checkout_payment((attempt->>'id')::uuid,'square-payment',5,'location','live','COMPLETED') FROM cof_fixture;
SELECT confirm_square_checkout_card(authorization_id,'square-customer','ccof:fixture','1111','VISA') FROM cof_fixture;
SELECT is((SELECT payment_status FROM square_live_test_checkouts WHERE token=(SELECT token FROM cof_fixture)),'paid','Confirmed $0.05 transaction recorded');
SELECT is((SELECT state FROM square_checkout_authorizations WHERE id=(SELECT authorization_id FROM cof_fixture)),'active','Confirmed Square Card ID activates recorded authorization');
SELECT is((SELECT get_square_live_test_details(token)->>'can_pay' FROM cof_fixture),'false','Paid test link no longer accepts payments');
SELECT record_square_checkout_payment((attempt->>'id')::uuid,'square-payment',5,'location','live','FAILED') FROM cof_fixture;
SELECT is((SELECT payment_status FROM square_live_test_checkouts WHERE token=(SELECT token FROM cof_fixture)),'paid','Late failure cannot downgrade completed test');
SELECT throws_like('UPDATE square_checkout_authorizations SET terms_text=''changed'' WHERE id=(SELECT authorization_id FROM cof_fixture)','%immutable%','Accepted terms cannot be rewritten');
SELECT throws_like('SELECT prepare_square_authorized_renewal(authorization_id,NULL,(SELECT user_id FROM profiles WHERE is_admin LIMIT 1),''location'') FROM cof_fixture','%reservation-specific%','Independent test authorization cannot charge any existing reservation');
SELECT withdraw_square_checkout_authorization(management_token) FROM square_checkout_authorizations WHERE id=(SELECT authorization_id FROM cof_fixture);
SELECT is((SELECT state FROM square_checkout_authorizations WHERE id=(SELECT authorization_id FROM cof_fixture)),'withdrawn','Withdrawal stops new charge instructions');
SELECT throws_like('SELECT claim_square_cof_dispatch(authorization_id,submission) FROM cof_fixture','%Valid payer consent%','Withdrawn authorization cannot dispatch');
SELECT is((SELECT jsonb_agg(to_jsonb(p)) FROM rental_extension_periods p),(SELECT renewal_snapshot FROM cof_fixture),'Existing renewal periods are completely unchanged');
SELECT is((SELECT count(*)::integer FROM booking_security_deposits),0,'No security deposit is created');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT throws_like('SELECT claim_square_cof_dispatch(authorization_id,submission) FROM cof_fixture','%permission denied%','Clients cannot claim privileged financial operations');
RESET ROLE;
